import asyncio
from collections import Counter
from pathlib import Path
from typing import Literal

import httpx
from pydantic import BaseModel, ConfigDict

KOLEO_STATIONS_URL = "https://api.koleo.pl/v2/main/stations"
KOLEO_HEADERS = {
    "X-KOLEO-Version": "2",
    "X-KOLEO-Client": "Nuxt-ef331c2",
    "Accept": "application/json",
}
HEADER = [
    '"""Generated by tools/station_generator. Do not edit."""',
    "",
    "from enum import StrEnum",
    "",
    "",
    "class Station(StrEnum):",
]


class KoleoStation(BaseModel):
    model_config = ConfigDict(frozen=True, extra="ignore")

    id: int
    name_slug: str


class StationEnumGenerator(BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid")

    type: Literal["station_enum_generator"] = "station_enum_generator"
    output: Path = Path("train_ticket_prices/stations.py")

    async def run(self) -> int:
        async with httpx.AsyncClient(timeout=60) as client:
            return await self.generate(client)

    async def generate(self, client: httpx.AsyncClient) -> int:
        response = await client.get(KOLEO_STATIONS_URL, headers=KOLEO_HEADERS)
        response.raise_for_status()
        stations = [
            KoleoStation.model_validate(item) for item in response.json()
        ]
        slug_counts = Counter(station.name_slug for station in stations)
        names = [self._member_name(station) for station in stations]
        name_counts = Counter(names)
        lines = [*HEADER]
        for station, name in zip(stations, names, strict=True):
            member = name if name_counts[name] == 1 else f"{name}_{station.id}"
            value = self._value(station, slug_counts)
            lines.append(f'    {member} = "{value}"')
        self.output.parent.mkdir(parents=True, exist_ok=True)
        self.output.write_text("\n".join(lines) + "\n", encoding="utf-8")
        return len(stations)

    @staticmethod
    def _member_name(station: KoleoStation) -> str:
        name = station.name_slug.upper().replace("-", "_")
        if not name.isidentifier() or name[0].isdigit():
            return f"S_{name}"
        return name

    @staticmethod
    def _value(station: KoleoStation, slug_counts: Counter[str]) -> str:
        if slug_counts[station.name_slug] == 1:
            return station.name_slug
        return f"{station.name_slug}-{station.id}"


if __name__ == "__main__":
    print(asyncio.run(StationEnumGenerator().run()))  # noqa: T201
